create extension if not exists pgcrypto;
create table if not exists categories(id uuid primary key default gen_random_uuid(),name text not null unique,slug text not null unique,sort_order int default 0,active boolean default true);
create table if not exists sports(id uuid primary key default gen_random_uuid(),name text not null unique,slug text not null unique,sort_order int default 0,active boolean default true);
create table if not exists posts(id uuid primary key default gen_random_uuid(),title text not null,slug text not null unique,category_id uuid references categories(id) on delete set null,sport_id uuid references sports(id) on delete set null,academic_year text default 'G10',event_date date,excerpt text default '',content text default '',reflection text default '',cover_image text default '',gallery jsonb default '[]'::jsonb,video_url text default '',tags text[] default '{}',featured boolean default false,published boolean default false,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists site_settings(id uuid primary key default gen_random_uuid(),current_grade text default 'Grade 10',school text default 'Chadwick International School',hero_title text default 'JACKSON HONG',hero_subtitle text default 'Student · Athlete · Writer · Explorer',hero_statement text default 'Curious about the world. Driven to explore it.',updated_at timestamptz default now());
create table if not exists timeline_items(id uuid primary key default gen_random_uuid(),year_label text,title text,description text,sort_order int default 0,published boolean default true);
create table if not exists awards(id uuid primary key default gen_random_uuid(),year_label text,title text,detail text,category text,sort_order int default 0,published boolean default true);
insert into site_settings default values on conflict do nothing;
insert into categories(name,slug,sort_order) values('Ideas','ideas',1),('Athletics','athletics',2),('Academics','academics',3),('Projects','projects',4),('Journey','journey',5) on conflict(slug) do nothing;
insert into sports(name,slug,sort_order) values('Swimming','swimming',1),('Golf','golf',2),('Soccer','soccer',3) on conflict(slug) do nothing;
alter table categories enable row level security; alter table sports enable row level security; alter table posts enable row level security; alter table site_settings enable row level security;
create policy "public categories" on categories for select using(active=true); create policy "public sports" on sports for select using(active=true); create policy "public posts" on posts for select using(published=true); create policy "public settings" on site_settings for select using(true);
create policy "authenticated categories" on categories for all to authenticated using(true) with check(true); create policy "authenticated sports" on sports for all to authenticated using(true) with check(true); create policy "authenticated posts" on posts for all to authenticated using(true) with check(true); create policy "authenticated settings" on site_settings for all to authenticated using(true) with check(true);
insert into storage.buckets(id,name,public) values('portfolio-media','portfolio-media',true) on conflict(id) do nothing;
create policy "media read" on storage.objects for select using(bucket_id='portfolio-media'); create policy "media admin upload" on storage.objects for insert to authenticated with check(bucket_id='portfolio-media'); create policy "media admin update" on storage.objects for update to authenticated using(bucket_id='portfolio-media'); create policy "media admin delete" on storage.objects for delete to authenticated using(bucket_id='portfolio-media');
